#!/usr/bin/env python3
"""Static source audit for PROTEST PARTY v0.8; not a Luau/runtime certification."""
from pathlib import Path
import json, sys, zipfile
ROOT=Path(__file__).resolve().parents[1]
checks=[]
def check(name, condition): checks.append((name,bool(condition)))
def read(path): return (ROOT/path).read_text(encoding="utf-8")
manifest=json.loads(read("default.project.json"))
config=read("src/ReplicatedStorage/Shared/GameConfig.lua")
profile=read("src/ServerScriptService/Services/ProfileService.lua")
bootstrap=read("src/ServerScriptService/Bootstrap.server.lua")
rounds=read("src/ServerScriptService/Services/RoundService.lua")
community=read("src/ServerScriptService/Services/DebateCommunityService.lua")
global_service=read("src/ServerScriptService/Services/GlobalDebateService.lua")
weekly=read("src/ServerScriptService/Services/WeeklyChampionshipService.lua")
social=read("src/ServerScriptService/Services/SocialSystemsService.lua")
social_hud=read("src/StarterPlayer/StarterPlayerScripts/SocialHUD.client.lua")
party=read("src/ServerScriptService/Services/PartyService.lua")
hud=read("src/StarterPlayer/StarterPlayerScripts/HUD.client.lua")
check("Rojo manifest parses",manifest.get("name")=="ProtestParty")
required=["src/ServerScriptService/Services/GlobalDebateService.lua","src/ServerScriptService/Services/WeeklyChampionshipService.lua","src/ServerScriptService/Services/PartyService.lua","src/ServerScriptService/Services/SocialSystemsService.lua","src/ServerScriptService/Services/DebateCommunityService.lua","src/ServerScriptService/Services/ProfileService.lua","src/ServerScriptService/Services/RoundService.lua","src/ServerScriptService/Bootstrap.server.lua","src/StarterPlayer/StarterPlayerScripts/HUD.client.lua","src/StarterPlayer/StarterPlayerScripts/SocialHUD.client.lua","docs/V0_8_SOCIAL_SYSTEMS.md","docs/PARTIES_AND_FACTION_WAR.md","docs/MODERATION_REVIEW_AND_AUDIT.md","docs/SECURITY_MODEL.md","docs/DATA_AND_MIGRATIONS.md","docs/QA_TEST_PLAN.md"]
for f in required: check("Required file: "+f,(ROOT/f).is_file())
check("Version is 0.8.0",'Version = "0.8.0"' in config)
check("Legacy round-robin faction service is removed",not (ROOT/"src/ServerScriptService/Services/FactionTournamentService.lua").exists())
check("RoundService uses the scheduled global debate prompt","GetScheduledDebate" in rounds and "debate and debate.id" in rounds)
check("Faction final prompt uses finalist names","sideA=factionA.name" in social and "sideB=factionB.name" in social)
check("Round results pass the debate identity to social systems","debate and debate.id or nil" in rounds)
check("Profile schema remains v3","ProfileSchemaVersion = 3" in config)
check("Existing live/studio DataStores preserved","ProtestParty_PlayerData_STUDIO" in config and "ProtestParty_PlayerData_LIVE" in config)
check("Stable User_<UserId> key retained",'return "User_" .. tostring(player.UserId)' in profile)
check("Profile persistence remains UpdateAsync","UpdateAsync" in profile and "SetAsync" not in profile)
check("Debate reputation remains independent","DebateReputation" in profile and "Coins" in profile)
check("Global topics use MemoryStore sorted map",'GetSortedMap("PP_GlobalDebates_v1")' in global_service)
check("Cross-server refresh uses MessagingService","SubscribeAsync" in global_service and "PublishAsync" in global_service)
check("Reports deduplicated by user/topic","REPORT_MAP:UpdateAsync(reportKey" in global_service)
check("Reports enter moderation review queue","REVIEW_MAP:SetAsync" in global_service and "reportCount >= 3" in global_service)
check("Review queue can be retrieved","function GlobalDebateService.GetReviewQueue()" in global_service)
check("Feature votes deduplicated","FEATURE_VOTE_MAP:UpdateAsync(markerKey" in global_service)
check("Community threshold is five","votes >= 5" in global_service)
check("Moderator feature requires community approval","topicRecord.communityApproved ~= true" in global_service)
check("Audit history uses DataStore UpdateAsync","AUDIT_STORE:UpdateAsync" in global_service)
check("Audit history capped to 50 actions","while #history > 50" in global_service)
check("Audit records actor and statuses","actorId=actorId" in global_service and "previousStatus=previousStatus" in global_service)
check("Moderator actions receive actor UserId","Moderate(topicId, action, player.UserId)" in community)
check("Moderation queue access is allowlist protected","isModerator(player)" in community and "GetModerationQueue" in community)
check("Moderation audit access is allowlist protected","GetModerationAudit" in community and "isModerator(player)" in community)
check("Topics filtered before global submission","GlobalDebateService.Submit(filtered" in community and "FilterStringAsync" in community)
check("Player categories filtered","cleanCategory" in community and "TextService:FilterStringAsync(category" in community)
check("Party remote registered by bootstrap",'getOrCreateRemote("Party")' in bootstrap and "PartyService.Start(partyRemote)" in bootstrap)
check("Party service limits group size to six","MAX_MEMBERS = 6" in party)
check("Party invitations expire","INVITE_TTL = 45" in party and "expiry<os.time()" in party)
check("Party IDs cannot collide on rapid recreation","HttpService:GenerateGUID(false)" in party)
check("Party invite spam is throttled","inviteAt[player.UserId] or 0)<5" in party)
check("Only leader may invite or kick","party.leader~=player.UserId" in party and 'elseif action=="Kick"' in party)
check("Party accepts exact in-server name/display name","candidate.Name)==query or string.lower(candidate.DisplayName)==query" in party)
check("Party membership clears on leave",'remote:FireClient(player,"PartyState",nil)' in party)
check("Party state is ephemeral and server-side","local parties:" in party and "DataStore" not in party)
check("Party snapshot exposes persistent creator club key","clubId=party.clubId" in party and 'clubId="club_"..tostring(player.UserId)' in party)
check("Faction war standings endpoint exists","GetWarState()" in social and 'action=="GetTournament"' in community)
check("HUD includes party controls","PartyCreate" in hud and "PartyInvite" in hud and "PartyKick" in hud and "PartyAccept" in hud)
check("HUD includes community feature vote","VoteFeatured" in hud)
check("HUD includes faction war bracket panel","payload.kind == \"FactionWar\"" in hud and "FACTION WAR" in hud)
check("HUD includes moderation queue and audit","OPEN REVIEW QUEUE" in hud and "AUDIT SELECTED" in hud and "RESTORE SELECTED" in hud)
check("Moderator controls default hidden","modQueueButton.Visible=false; modAuditButton.Visible=false" in hud)
check("No client-supplied reward values accepted","CommunityCoins" not in community and "CommunityXP" not in community)
check("Social remote is registered and started",'getOrCreateRemote("SocialSystems")' in bootstrap and "SocialSystemsService.Start(socialRemote" in bootstrap)
check("Social identity uses separate persistent store",'GetDataStore("PP_SocialIdentity_v1")' in social)
check("Existing profile schema remains independent",'ProfileSchemaVersion = 3' in config and "PP_SocialIdentity_v1" in social)
check("Public identity contains badges and history","badges=profile.badges" in social and "history=profile.history" in social)
check("Titles require server-side badge unlock","titleBadges[title]" in social and "profile.badges" in social)
check("User bios are filtered before storage","filteredText(player,bio)" in social and "TextService" in social)
check("Coordinated party protest requires party proximity","JoinPartyProtest" in social and "Magnitude>70" in social)
check("Party reputation is persistent","PP_PartyReputation_v1" in social and "UpdateAsync(clubId" in social)
check("Party and debate activity contribute to faction war","factionScoreStore():IncrementAsync" in social and "OnRoundResults" in social)
check("Faction war scores are split into per-week ordered store",'GetOrderedDataStore("PP_FactionWarScores_"..weekKey())' in social)
check("Weekly store key uses Monday UTC week anchor","weekStartTimestamp" in social and "local weekStart=math.floor" in read("src/ServerScriptService/Services/WeeklyChampionshipService.lua"))
check("Faction war persists weekly bracket and territory","PP_FactionWar_v1" in social and 'data.bracket.phase="FINAL"' in social and "data.territories={}; data.territories[finalWinner]=true" in social)
check("Faction final has scheduled UTC phase",'finalSchedule="FRIDAY 18:00 UTC"' in social and "hour>=18" in social)
check("Faction final uses the scheduled finalist debate","factionfinal:" in social and "GetScheduledDebate" in social and "eventResult.debateId==\"factionfinal:\"..weekKey()" in social)
check("Global event result and faction final share one canonical result","recordGlobalEventResult" in social and "eventResult.result" in social and "eventResult.debateId" in social)
check("Semifinal schedule worker advances without a round result","RefreshTournamentSchedule" in social and "task.wait(30)" in social)
check("Faction trophy and plaza evolution exist","FactionWarTrophy" in social and "TerritoryFlag_" in social and "TerritoryDialogue" in social)
check("Global debate event has daily UTC schedule","dayStart+18*3600" in social and "predictionClosesAt=starts+1800" in social)
check("Predictions are stored in MemoryStore","PP_EventPredictions_v1" in social and "PredictionMap:UpdateAsync" in social)
check("Global event result is atomically claimed",'result:"..event.id' in social and "PP_GlobalEventMarkers_v1" in social)
check("Spectator vote payload is bounded","count>=300" in social and "vote:" in social)
check("Prediction UI receives aggregate counts, not the raw vote ledger","predictions=summary" in social and "myPrediction=predictions.votes" in social and "predictions=if ok and type(predictions)==\"table\" then predictions" not in social)
check("Debate participants are excluded from spectator predictions","debateParticipants" in social and "excludedParticipants" in social and "debateVotes)" in rounds)
check("Faction bracket does not advance on failed score reads","scoresAvailable==true" in social and "bracketAvailable==true" in social)
check("Cross-server event broadcast uses MessagingService","PP_GlobalDebateBroadcast_v1" in social and "PublishAsync" in social and "SubscribeAsync" in social)
check("Moderation cases are durable and GUID based","PP_ModerationCases_v1" in social and "GenerateGUID(false)" in social)
check("Staff actions are moderator allowlist gated","GetStaffDashboard" in social and "not moderator(player)" in social)
check("Case notes are filtered and audited","filteredText(player,note)" in social and "NOTE_ADDED" in social and "old.audit" in social)
check("Case IDs are bounded before DataStore access","validCaseId" in social and "#value<=48" in social)
check("Appeals are limited to the reported player","case.target~=player.UserId" in social and "APPEAL_SUBMITTED" in social)
check("Moderators can accept or reject appeals","DecideAppeal" in social and "APPEAL_ACCEPTED" in social and "APPEAL_REJECTED" in social)
check("Social HUD exposes party, profile, event, and staff actions","StartPartyProtest" in social_hud and "GetIdentity" in social_hud and "Predict" in social_hud and "GetStaffDashboard" in social_hud)
check("Championship broadcasts have an animated top banner","ChampionshipBroadcastBanner" in social_hud and "TweenService:Create" in social_hud)
check("Social Hub staggers initial requests around server throttles","task.delay(.5" in social_hud and "task.delay(1" in social_hud)
check("Staff case list supports interactive case selection","caseList" in social_hud and "caseIdBox.Text=tostring(case.id)" in social_hud)
check("Staff-only controls are hidden until allowlist authorization","staffOnly" in social_hud and "element.Visible=data.enabled==true" in social_hud)
check("Staff dashboard supports assignment to another allowlisted moderator","assignUserBox" in social_hud and "AssignCase" in social and "allowedAssignee" in social)
check("Social HUD resizes for narrow screens","ViewportSize" in social_hud and "viewport.X<420" in social_hud)
failed=[n for n,ok in checks if not ok]
for n,ok in checks: print(("PASS" if ok else "FAIL")+"  "+n)
print(f"\n{len(checks)-len(failed)}/{len(checks)} static checks passed")
if failed: sys.exit(1)
